INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (8, 'Mesin tidak menjalankan siklus bartack', 'Mesin tidak memulai siklus jahitan penguat atau siklus berhenti sebelum selesai.', 'Pola tidak dipilih dengan benar, work clamp tidak berada pada posisi yang sesuai, atau sistem kontrol dan penggerak mengalami gangguan.', 'Periksa pemilihan pola, posisi work clamp, dan kondisi sistem kontrol. Pastikan material terpasang dengan benar sebelum memulai siklus.', 'Matikan mesin sebelum memeriksa area mekanis atau melakukan penyetelan work clamp.', 'Data spesifikasi JUKI LK-1900C dan panduan pemeriksaan umum');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (8, 'Pola bartack tidak sesuai', 'Bentuk atau arah jahitan penguat berbeda dari pola yang dipilih.', 'Data pola yang dipilih tidak sesuai, parameter pola berubah, atau sistem feed X/Y tidak bekerja sesuai perintah.', 'Periksa nomor pola dan parameter jahitan. Pastikan gerakan feed lateral dan longitudinal sesuai dengan pola yang diprogram.', 'Matikan mesin sebelum melakukan pemeriksaan mekanis pada sistem feed.', 'Data spesifikasi pola dan feed JUKI LK-1900C');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (8, 'Posisi bartack bergeser', 'Jahitan penguat tidak berada pada posisi yang diinginkan pada material.', 'Posisi material atau work clamp kurang tepat, atau gerakan feed X/Y tidak sesuai.', 'Periksa posisi material dan work clamp. Periksa juga parameter posisi serta gerakan feed dalam arah lateral dan longitudinal.', 'Matikan mesin sebelum menyetel work clamp atau mekanisme feed.', 'Data spesifikasi sewing area dan feed JUKI LK-1900C');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (8, 'Benang jarum sering putus', 'Benang jarum putus selama proses bartack atau jahitan tidak dapat diselesaikan.', 'Jarum tidak sesuai atau rusak, jalur benang kurang tepat, atau needle thread tension terlalu tinggi.', 'Periksa kondisi dan pemasangan jarum DP×5 atau DP×17 sesuai subclass. Periksa jalur benang dan pengaturan active tension.', 'Matikan mesin sebelum mengganti jarum atau melakukan penyetelan tension.', 'Data spesifikasi needle dan active tension JUKI LK-1900C');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (8, 'Jahitan bartack longgar atau tidak kuat', 'Jahitan penguat terlihat longgar, tidak rapat, atau kekuatan jahitan tidak sesuai.', 'Parameter stitch length atau tension tidak sesuai, kondisi jarum kurang baik, atau hook tidak bekerja normal.', 'Periksa stitch length, active tension, jarum, dan hook. Sesuaikan parameter dengan material dan pola bartack yang digunakan.', 'Matikan mesin sebelum memeriksa hook atau mengganti jarum.', 'Data spesifikasi stitch length, tension, needle, dan hook JUKI LK-1900C');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (8, 'Work clamp tidak mengangkat atau menjepit dengan benar', 'Work clamp tidak berada pada ketinggian yang sesuai atau material tidak terjepit stabil.', 'Auto-lifter mengalami gangguan atau mekanisme work clamp tidak bergerak normal.', 'Periksa gerakan work clamp dan auto-lifter. Pastikan ketinggian clamp berada dalam batas spesifikasi dan material terjepit stabil.', 'Matikan mesin sebelum memeriksa mekanisme clamp atau auto-lifter.', 'Data spesifikasi work clamp foot lift dan auto-lifter JUKI LK-1900C');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (8, 'Pola atau data jahitan tidak tersimpan atau tidak sesuai', 'Pola yang dipanggil tidak sesuai atau data jahitan tidak dapat digunakan seperti yang diharapkan.', 'Data pola atau parameter tidak sesuai, atau penggunaan memori tidak dilakukan dengan benar.', 'Periksa data pola yang dipilih dan parameter pembesaran atau pengecilan. Pastikan data yang digunakan tersimpan pada internal memory dengan benar.', 'Jangan melakukan perubahan data pola saat mesin sedang menjalankan siklus jahit.', 'Data spesifikasi internal memory dan pattern data JUKI LK-1900C');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (8, 'Pelumasan atau motor tidak normal', 'Gerakan mesin terasa kasar, suara mekanis meningkat, atau motor tidak bekerja normal.', 'Pelumasan hook tidak mencukupi atau sistem direct-drive servomotor mengalami gangguan.', 'Periksa pelumasan minute-quantity pada hook dan gunakan JUKI New Defrix Oil No. 2 / ISO VG32 sesuai spesifikasi. Jika motor tetap bermasalah, lakukan pemeriksaan sistem penggerak.', 'Matikan mesin dan putuskan sumber listrik sebelum melakukan pelumasan atau pemeriksaan motor.', 'Data spesifikasi lubrication dan motor JUKI LK-1900C');
